package password_test

import (
	"strings"
	"testing"

	"github.com/fikrilal/go-core-kit/internal/platform/password"
)

// Generated by backend-core-kit's @node-rs/argon2 (Algorithm.Argon2id, library defaults).
const (
	referenceHash     = "$argon2id$v=19$m=19456,t=2,p=1$W+k2JnwY3cE77Mrpw98+xA$gIoFA9p3kui4PjaZcZK+yePiV6Kjr2kou6lGJfOwFms"
	referencePassword = "correct-horse-battery-staple"
)

func TestVerifyAcceptsReferenceHash(t *testing.T) {
	ok, err := password.New().Verify(referenceHash, referencePassword)
	if err != nil {
		t.Fatalf("Verify(reference) error = %v", err)
	}
	if !ok {
		t.Fatal("Verify(reference) = false, want true (cross-kit compatibility)")
	}
}

func TestVerifyRejectsWrongPassword(t *testing.T) {
	ok, err := password.New().Verify(referenceHash, "not-the-password")
	if err != nil {
		t.Fatalf("Verify(wrong) error = %v", err)
	}
	if ok {
		t.Fatal("Verify(wrong) = true, want false")
	}
}

func TestHashRoundTrip(t *testing.T) {
	hasher := password.New()
	encoded, err := hasher.Hash("correct-horse-battery-staple")
	if err != nil {
		t.Fatalf("Hash() error = %v", err)
	}
	if !strings.HasPrefix(encoded, "$argon2id$v=19$m=19456,t=2,p=1$") {
		t.Fatalf("Hash() = %q, want the reference PHC prefix", encoded)
	}
	for _, segment := range strings.Split(encoded, "$")[4:] {
		if strings.Contains(segment, "=") {
			t.Fatalf("Hash() = %q, want unpadded base64 segments", encoded)
		}
	}
	ok, err := hasher.Verify(encoded, "correct-horse-battery-staple")
	if err != nil || !ok {
		t.Fatalf("Verify(own hash) = %v, %v, want true, nil", ok, err)
	}
	other, err := hasher.Hash("correct-horse-battery-staple")
	if err != nil {
		t.Fatalf("Hash() second error = %v", err)
	}
	if other == encoded {
		t.Fatal("Hash() produced identical output twice; salt must be random")
	}
}

func TestVerifyRejectsMalformedHashes(t *testing.T) {
	cases := []string{
		"",
		"plaintext",
		"$argon2i$v=19$m=19456,t=2,p=1$c2FsdA$aGFzaA",
		"$argon2id$v=13$m=19456,t=2,p=1$c2FsdA$aGFzaA",
		"$argon2id$v=19$m=0,t=0,p=0$c2FsdA$aGFzaA",
		"$argon2id$v=19$m=19456,t=2,p=1$!!!$aGFzaA",
		"$argon2id$v=19$m=19456,t=2,p=1$c2FsdA$!!!",
	}
	for _, encoded := range cases {
		if _, err := password.New().Verify(encoded, "pw"); err == nil {
			t.Errorf("Verify(%q) = nil error, want malformed-hash error", encoded)
		}
	}
}
